UPDATE RESUME
SET RESUME_HIDE_FL = #{value}
WHERE RESUME_NO = #{resumeNo}

UPDATE RESUME
SET RESUME_DEL_FL = #{value}
WHERE RESUME_NO = #{resumeNo}

mapper.select:
SELECT A.RESUME_CONTENT AS RESUME_CONTENT, A.RESUME_DEL_FL AS RESUME_DEL_FL, A.RESUME_HIDE_FL AS RESUME_HIDE_FL, A.RESUME_NO AS RESUME_NO, A.RESUME_TITLE AS RESUME_TITLE, A.GRADE_NO AS GRADE_NO, A.PERIOD_NO AS PERIOD_NO, A.SALARY_AMOUNT AS SALARY_AMOUNT, A.SALARY_NO AS SALARY_NO, A.REGISTRATION_DATE AS REGISTRATION_DATE, A.MODIFICATION_DATE AS MODIFICATION_DATE,
B.BLIND_LOGIN_ID AS BLIND_LOGIN_ID, B.FAST_LOGIN_TOKEN AS FAST_LOGIN_TOKEN, B.PROFILE_IMG AS PROFILE_IMG, B.SIGN_UP_PATH AS SIGN_UP_PATH, REGEXP_REPLACE(REGEXP_REPLACE(B.WORKER_ADDRESS, '^\d+\^\^\^', ''), '\^\^\^', '') AS WORKER_ADDRESS, TO_CHAR(B.WORKER_BIRTHDATE, 'YYYY') AS WORKER_BIRTHDATE, B.WORKER_BIRTHDATE, FLOOR(MONTHS_BETWEEN(TRUNC(SYSDATE), B.WORKER_BIRTHDATE) / 12) AS AGE, B.WORKER_ID AS WORKER_ID, B.WORKER_MBTI AS WORKER_MBTI, B.WORKER_NICKNAME AS WORKER_NICKNAME, B.WORKER_NO AS WORKER_NO,
C.AUTHORITY_NO AS AUTHORITY_NO, C.ENROLL_DATE AS ENROLL_DATE, C.MEMBER_DEL_FL AS MEMBER_DEL_FL, C.MEMBER_EMAIL AS MEMBER_EMAIL, C.MEMBER_NAME AS MEMBER_NAME, C.MEMBER_NO AS MEMBER_NO, C.MEMBER_PW AS MEMBER_PW, SUBSTR(C.MEMBER_TEL, 1, 3) || '-' || SUBSTR(C.MEMBER_TEL, 4, 4) || '-' || SUBSTR(C.MEMBER_TEL, 8, 4) AS MEMBER_TEL FROM RESUME A LEFT JOIN WORKER B ON A.WORKER_NO = B.WORKER_NO LEFT JOIN MEMBER C ON B.MEMBER_NO = C.MEMBER_NO WHERE A.RESUME_NO = #{resumeNo}
